const C=window.CONTENT;
const paths={drop:'<path d="M12 2s-8 9-8 14a8 8 0 0 0 16 0c0-5-8-14-8-14Z"/><path d="M12 9s-4 5-4 7a4 4 0 0 0 8 0c0-2-4-7-4-7Z"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',leaf:'<path d="M21 3C8 2 1 10 5 17s17 3 16-14Z"/><path d="M3 22 17 8"/>',wa:'<path d="M21 11.5a9 9 0 0 1-13.3 8L3 21l1.5-4.7A9 9 0 1 1 21 11.5Z"/><path d="M8 7c0 5 4 9 8 9l1-3-3-1-1 1-3-3 1-1-1-3Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',fold:'<path d="M4 6h16v4H4zM3 12h18v4H3zM4 18h16v3H4z"/><path d="M7 7h10M7 13h10"/>',hanger:'<path d="m7 5 5 3 5-3 5 4-4 6-2-2v9H8v-9l-2 2-4-6Z"/><path d="m9 6 3 8 3-8M12 14v8"/>',curtain:'<path d="M2 3h20M4 4v18l6-3-4-9M20 4v18l-6-3 4-9M7 4l3 15M17 4l-3 15"/>',shoe:'<path d="M4 6h5l3 8 8 2 2 3v3H2v-6Z"/><path d="m10 10 4-1m-3 4 4-1M3 18h18"/>',bag:'<path d="M4 8h16l2 14H2ZM8 8V5a4 4 0 0 1 8 0v3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18m-13 4h2m4 0h2m-8 3h2"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.spark}</svg>`;
const logo=()=>`<a class="logo" href="/" aria-label="Bros Jay Laundry home">${icon('drop')}<span>Bros Jay<small>LAUNDRY</small></span></a>`;
const wa=(text='Chat on WhatsApp',cls='')=>`<button class="btn wa ${cls}" data-wa>${icon('wa')}<span>${text}</span></button>`;
const book=(text='Book now',cls='')=>`<a class="btn ${cls}" href="/book">${text}${icon('arrow')}</a>`;
const money=n=>'₦'+n.toLocaleString('en-NG');
const payment='Payment (cash or bank transfer) is due before your clothes are released.';
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function hero(tag,title,desc){return `<div class="hero page-hero"><div class="wrap"><div class="hero-copy"><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${desc}</p></div></div></div>`}
function serviceCards(home=false){return `<div class="cards ${home?'home-services':''}">${C.services.map(s=>`<article class="service"><div class="service-art service-photo ${s.image}" role="img" aria-label="${escapeHTML(s.name)}"></div><div class="service-body"><h3>${s.name}</h3><div class="price">${money(s.price)}<small>+</small></div><p>${s.description}</p><a class="text-link" href="/book?service=${s.id}">Book this service ↗</a></div></article>`).join('')}</div>`}
function policy(){return `<div class="policy">${icon('shield')}<span>${payment}</span></div>`}
function form(){return `<form id="booking" class="form-card" novalidate><h3>Book your laundry service</h3><div class="toggle"><label><input type="radio" name="handover" value="dropoff" checked>Drop-off (at shop)</label><label><input type="radio" name="handover" value="pickup">Pick-up (from address)</label></div><div class="notice">Choose your service and send your request. We’ll confirm the details with you.</div><div class="form-grid"><div><label for="name">Full name</label><input id="name" name="name" autocomplete="name" maxlength="80" placeholder="Enter your full name" required><div class="error" data-error="name"></div></div><div><label for="phone">Phone number</label><input id="phone" name="phone" type="tel" autocomplete="tel" maxlength="18" placeholder="e.g. 0803 123 4567" required><div class="error" data-error="phone"></div></div><div class="full"><label for="service">Service</label><select id="service" name="service" required><option value="">Select a service</option>${C.services.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select><div class="error" data-error="service"></div></div><div class="full" id="pickupFields" hidden><div class="form-grid"><div><label for="date">Pick-up date</label><input id="date" name="date" type="date"><div class="date-note">Monday–Saturday · next 14 days</div><div class="error" data-error="date"></div></div><div><label for="time">Pick-up time</label><select id="time" name="time"><option value="">Choose date first</option></select><div class="date-note">Africa/Lagos time</div><div class="error" data-error="time"></div></div><div class="full"><label for="area">Area</label><select name="area" id="area"><option value="">${C.areas.length?'Select your area':'Service areas awaiting confirmation'}</option>${C.areas.map(a=>`<option>${escapeHTML(a)}</option>`).join('')}</select><div class="error" data-error="area"></div>${C.areas.length?'':'<div class="date-note">Please choose drop-off until pick-up areas are confirmed.</div>'}</div><div class="full"><label for="address">Street address</label><input id="address" name="address" maxlength="200" autocomplete="street-address" placeholder="House number and street"><div class="error" data-error="address"></div></div><div class="full"><label for="landmark">Landmark or directions</label><input id="landmark" name="landmark" maxlength="200" placeholder="A nearby landmark to help us find you"><div class="error" data-error="landmark"></div></div></div></div></div><div class="shop-info" id="shopInfo"><b>Drop off at our shop</b><br>${C.address}<br>${C.hours}</div><label class="consent"><input type="checkbox" id="consent" name="consent"> <span>I agree that you may use my details to arrange this booking. <a href="/privacy">Privacy notice</a></span></label><div class="error" data-error="consent"></div><div class="honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><p class="form-note">${payment}<br>We'll confirm your price and pick-up time with you.</p><button class="btn submit" type="submit">${icon('calendar')} Submit booking request</button><div id="formStatus" role="status"></div><div class="safe">${icon('shield')}Your details are used only to arrange your booking.</div></form>`}
function home(){return `<div class="hero"><div class="wrap"><div class="hero-copy"><span class="eyebrow">CLEAN CLOTHES · FRESH FEELING</span><h1>Professional Laundry<br>Services You Can Trust</h1><p>Clean. Fresh. On time. We take care of your clothes so you can focus on what matters.</p><div class="actions">${book('Book a service')}<a class="btn outline" href="/prices">See services & prices</a></div></div><span class="hero-note">Fresh<br>& Clean</span></div></div><div class="trust-strip"><div class="wrap">${[['shield','Careful handling','A little care in every load.'],['clock','Easy booking','Laundry that fits your day.'],['spark','A fresh start','Care for the clothes you love.'],['leaf','Clear prices','Confirm your price before cleaning.']].map(x=>`<div class="trust-item">${icon(x[0])}<div><b>${x[1]}</b><span>${x[2]}</span></div></div>`).join('')}</div></div><section><div class="wrap"><div class="section-heading"><span class="eyebrow">A LITTLE LESS LAUNDRY. A LITTLE MORE LIFE.</span><h2>Our Services & Prices</h2><p>Care for your everyday essentials and your special pieces. <span class="sample">SAMPLE RATES</span></p></div>${serviceCards(true)}<p style="text-align:center;font-size:11px;color:var(--muted);margin:20px 0 0">Final price is confirmed after we see your clothes.</p></div></section><section class="steps" id="how-it-works"><div class="wrap"><div class="section-heading"><span class="eyebrow">LAUNDRY DAY, MADE SIMPLE</span><h2>Fresh clothes in three easy steps.</h2></div><div class="step-grid">${[['Book online','Choose your service and tell us whether you’ll drop off or need a pick-up.'],['We confirm. We clean.','We’ll contact you to confirm your price and arrangements, then take care of your clothes.'],['Pay & feel fresh','Pay by cash or bank transfer and collect your clean, fresh clothes.']].map((x,i)=>`<div class="step"><span class="step-number">0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div>${policy()}</div></section><section><div class="wrap booking-block"><div class="booking-promo"><div><span class="eyebrow">LET US TAKE THE LOAD OFF</span><h2>Book Your<br>Laundry Service</h2><p>Choose drop-off or pick-up, fill in the form, and we’ll take it from there.</p></div><div class="promo-bottom">${icon('calendar')}<span><b>Pick-up: Monday–Saturday</b><br>8:00 a.m. – 9:00 p.m.<br>No pick-ups on Sundays.</span></div></div>${form()}</div></section><section class="info-section" id="about"><div class="wrap about-grid"><div class="about-image"><span>Clean clothes create confidence.</span></div><div><span class="eyebrow">A FRESH APPROACH TO LAUNDRY</span><h2>Good care.<br>From start to finish.</h2><p style="color:var(--muted);font-size:14px">${C.about}</p><span class="sample">ABOUT & TRUST COPY · DRAFT FOR REVIEW</span><div class="reasons">${[['shield','Thoughtful care','Careful handling for your everyday favourites.'],['clock','Made convenient','Choose drop-off or request a pick-up.'],['leaf','No surprises','We confirm the price after seeing your clothes.'],['spark','People first','A simple booking and a personal follow-up.']].map(x=>`<div class="reason">${icon(x[0])}<h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></div></div></section>${C.testimonials.length>=3?`<section><div class="wrap"><h2>Real people. Fresh stories.</h2><div class="cards">${C.testimonials.map(t=>`<blockquote class="form-card">${escapeHTML(t.quote)}<p>${escapeHTML(t.name)}</p></blockquote>`).join('')}</div></div></section>`:''}<section><div class="wrap"><div class="cta"><div><h2>Your laundry. Our care.</h2><p>Make a little more room for the things you love.</p></div>${book('Book a service')}</div></div></section>`}
function prices(){return hero('OUR SERVICES','Services & Prices','Quality laundry and dry cleaning care for your everyday life.')+`<section><div class="wrap"><div class="section-top"><p style="margin:0;color:var(--muted);font-size:13px">Sample starting rates. Final price is confirmed after we see your clothes.</p><span class="sample">SAMPLE PRICES</span></div>${serviceCards()}<div class="policy">${icon('leaf')}<div><h3>Pick-up areas & fees</h3><span>${C.areas.length?C.areas.join(', '):'Service areas and pick-up or delivery fees are awaiting owner confirmation. Visit our shop at Awo Hall, Block 7, Room 113, Ife, Osun State, from 9:00 a.m. to 8:00 p.m. Message us on WhatsApp to ask about pick-up in your neighbourhood.'}</span></div></div></div></section>`}
function bookPage(){return hero('YOUR NEXT FRESH START','Book Your Laundry Service','A few details, and we’ll take it from there. Quick, simple and convenient.')+`<section><div class="wrap booking-page">${form()}<aside class="sidebar">${icon('calendar')}<h3>Pick-up information</h3><p>Monday to Saturday<br><b>8:00 a.m. – 9:00 p.m.</b><br>No pick-ups on Sundays.</p><p>Book at least 3 hours ahead, up to 14 days in advance.</p><hr>${icon('shield')}<h3>Payment</h3><p>${payment}</p><hr><h3>A personal follow-up</h3><p>Your booking is a request. We’ll contact you by WhatsApp or call to confirm your price and arrangements.</p></aside></div></section>`}
function faq(){return hero('FREQUENTLY ASKED QUESTIONS','Got Questions?','A little clarity before your next laundry day.')+`<section><div class="wrap faq"><div class="notice">Policy answers are drafts for owner review. Please confirm business details before booking.</div>${C.faq.map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}<div class="cta"><div><h3>Still have a question?</h3><p>We’re a message away. Let’s talk laundry.</p></div>${wa()}</div></div></section>`}
function privacy(){return hero('YOUR DETAILS, TREATED WITH CARE','Privacy Notice','Draft notice for owner review before bookings go live.')+`<section><div class="wrap prose"><p>We collect only the details needed to arrange your laundry booking: name, phone number, service and handover choice. For pick-up, we also collect your requested date, time, area, address and landmark.</p><h2>How your information is used</h2><p>With your consent, we use your information to contact you and arrange the service. When connected, booking details are sent to the owner’s private Google Sheet and email. We do not create customer accounts or send marketing messages.</p><h2>Who can see your details</h2><p>The laundry owner and staff who need the information to arrange your service. Google processes the booking Sheet and email. Retention periods and the business data controller’s contact details must be confirmed before launch.</p><h2>Your choices</h2><p>You may request access, correction or deletion of your details by contacting the owner. Your rights apply under the Nigeria Data Protection Act 2023. Contact us on WhatsApp at +234 901 578 4157 or email psalmy37@gmail.com to request access, correction or deletion.</p><h2>Local storage</h2><p>We do not use advertising or analytics cookies. After a successful connected booking, a temporary confirmation summary is stored in this browser’s session so you can view your request.</p></div></section>`}
function thanks(){let b;try{b=JSON.parse(sessionStorage.getItem('bookingConfirmation'))}catch{}if(!b)return hero('BOOKING','No booking to show yet.','Complete the booking form to send your request.')+`<section class="empty">${book()}</section>`;return hero('THANK YOU','Your request is with us.',`Booking reference: ${escapeHTML(b.reference)}`)+`<section><div class="wrap prose"><h2>We’ll be in touch.</h2><p>The owner will contact you soon by WhatsApp or call to confirm your price and arrangements.</p><div class="form-card">${Object.entries(b.details).map(([k,v])=>`<p><b>${escapeHTML(k)}:</b> ${escapeHTML(v)}</p>`).join('')}</div>${policy()}<div class="actions">${wa()}</div></div></section>`}
function render(){let p=location.pathname.replace(/\/$/,'')||'/';document.getElementById('header').innerHTML=`<div class="wrap">${logo()}<nav aria-label="Main navigation"><a href="/" class="${p==='/'?'active':''}">Home</a><a href="/prices" class="${p==='/prices'?'active':''}">Services & Prices</a><a href="/#how-it-works">How it works</a><a href="/faq" class="${p==='/faq'?'active':''}">FAQ</a><a href="#contact" data-wa>Contact</a></nav><a class="btn book-btn" href="/book">Book now</a><button class="menu" aria-label="Open menu" aria-expanded="false">☰</button></div>`;document.getElementById('app').innerHTML=p==='/'?home():p==='/prices'?prices():p==='/book'?bookPage():p==='/faq'?faq():p==='/privacy'?privacy():p==='/book/thanks'?thanks():hero('PAGE NOT FOUND','A little lost in the wash?','Let’s get you back to something fresh.')+`<section class="empty"><a class="btn" href="/">Back to Home</a> ${book()}</section>`;document.getElementById('footer').innerHTML=`<div class="wrap"><div class="footer-top"><div>${logo()}<p>${C.tagline}<br>Thoughtful laundry care, made simple.</p></div><div><h3>Quick links</h3><div class="footer-links"><a href="/prices">Services & Prices</a><a href="/book">Book a service</a><a href="/#how-it-works">How it works</a><a href="/faq">FAQ</a><a href="/#about">About us</a><a href="/privacy">Privacy</a></div></div><div><h3>Visit & get in touch</h3><p>${C.address}<br>${C.hours}<br><a href="tel:+2349015784157">${C.phone||'Phone number to be confirmed'}</a><br><a href="mailto:${C.email}">${C.email}</a></p></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Bros Jay Laundry. All rights reserved.</span><span>Clean clothes. Happy you.</span></div></div>`;document.getElementById('float').innerHTML=`<div class="floating">${wa()}</div>`;document.querySelector('.menu').onclick=e=>{let n=document.querySelector('nav');n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',n.classList.contains('open'))};document.querySelectorAll('[data-wa]').forEach(el=>el.onclick=e=>{e.preventDefault();openWA()});document.querySelectorAll('.close,.close-contact').forEach(el=>el.onclick=()=>document.querySelector('dialog').close());setupForm();}
function openWA(message="Hello, I'd like to ask about your laundry service."){if(!C.whatsapp){document.querySelector('dialog').showModal();return}window.open('https://wa.me/'+C.whatsapp.replace(/\D/g,'')+'?text='+encodeURIComponent(message),'_blank','noopener,noreferrer')}
function lagosNow(){return new Date(Date.now()+3600000)}
function dateKey(d){return d.toISOString().slice(0,10)}
function normalizePhone(v){let p=v.replace(/[\s()-]/g,'');if(/^0[789]\d{9}$/.test(p))p='+234'+p.slice(1);else if(/^234[789]\d{9}$/.test(p))p='+'+p;return /^\+234[789]\d{9}$/.test(p)?p:null}
function availableTimes(date){let now=lagosNow(),today=dateKey(now);if(!date||date<today||date>dateKey(new Date(now.getTime()+C.pickup.maxDays*86400000))||new Date(date+'T12:00:00Z').getUTCDay()===0)return[];let times=[];for(let m=C.pickup.start*60;m<=C.pickup.end*60;m+=C.pickup.step){if(date===today&&m<now.getUTCHours()*60+now.getUTCMinutes()+C.pickup.leadHours*60)continue;let h=Math.floor(m/60),mm=m%60;times.push({value:`${String(h).padStart(2,'0')}:${String(mm).padStart(2,'0')}`,label:`${h%12||12}:${String(mm).padStart(2,'0')} ${h<12?'a.m.':'p.m.'}`})}return times}
function setupForm(){const f=document.getElementById('booking');if(!f)return;f.addEventListener('focusin',()=>{getChallenge().catch(()=>{})},{once:true});loadVerification().catch(()=>{});let n=lagosNow();f.date.min=dateKey(n);f.date.max=dateKey(new Date(n.getTime()+C.pickup.maxDays*86400000));f.service.value=new URLSearchParams(location.search).get('service')||'';f.querySelectorAll('[name=handover]').forEach(r=>r.onchange=()=>{let p=f.handover.value==='pickup';document.getElementById('pickupFields').hidden=!p;document.getElementById('shopInfo').hidden=p});f.date.onchange=()=>{const ts=availableTimes(f.date.value);f.time.innerHTML='<option value="">Select a time</option>'+ts.map(t=>`<option value="${t.value}">${t.label}</option>`).join('');f.querySelector('[data-error=date]').textContent=ts.length?'':'Choose Monday–Saturday within the next 14 days, with at least 3 hours’ notice.'};f.onsubmit=async e=>{e.preventDefault();if(f.dataset.sending==='true')return;f.querySelectorAll('[data-error]').forEach(x=>x.textContent='');let errors={},d=Object.fromEntries(new FormData(f));if(!d.name?.trim())errors.name='Please enter your full name.';if(!normalizePhone(d.phone||''))errors.phone='Enter a valid Nigerian number, e.g. 0803 123 4567.';if(!C.services.some(s=>s.id===d.service))errors.service='Choose a service.';if(d.handover==='pickup'){if(!availableTimes(d.date).length)errors.date='Choose an available Monday–Saturday in the next 14 days.';if(!availableTimes(d.date).some(t=>t.value===d.time))errors.time='Choose an available pick-up time.';if(!C.areas.includes(d.area))errors.area='Pick-up areas are not confirmed. Please choose drop-off.';for(let k of ['address','landmark'])if(!d[k]?.trim())errors[k]='Please add '+(k==='address'?'your street address.':'a landmark or directions.')}if(!d.consent)errors.consent='Please agree so we can arrange your booking.';for(let k in errors)f.querySelector(`[data-error=${k}]`).textContent=errors[k];if(Object.keys(errors).length){f.querySelector(`[name=${Object.keys(errors)[0]}]`).focus();return}if(d.website)return;d.phone=normalizePhone(d.phone);const status=document.getElementById('formStatus');if(!C.bookingEndpoint || !C.turnstileSiteKey){status.innerHTML='<p class="error">Your request has not been sent online. Please send your details directly on WhatsApp while booking notifications are being connected.</p><button type="button" class="btn wa" id="directBooking">Send booking on WhatsApp</button>';document.getElementById('directBooking').onclick=()=>openWA('Laundry booking request\n'+Object.entries(d).filter(([k])=>!['consent','website'].includes(k)).map(([k,v])=>k+': '+v).join('\n'));return}let btn=f.querySelector('[type=submit]');f.dataset.sending='true';btn.disabled=true;btn.setAttribute('aria-busy','true');btn.innerHTML='<span class="spinner" aria-hidden="true"></span> Sending your request…';status.innerHTML='<p class="sending-note">Please keep this page open while we send your booking.</p>';let slowTimer;try{d.challenge=await getChallenge();if(challengeState)discardChallenge(challengeState);status.innerHTML='<p class="sending-note">Sending your booking to Bros Jay…</p>';slowTimer=setTimeout(()=>{status.innerHTML='<p class="sending-note">Your booking is still sending. Please don’t submit again.</p>'},7000);let res=await fetch(C.bookingEndpoint,{method:'POST',body:JSON.stringify(d)});let r=await res.json();if(!r.success||!r.reference)throw Error();let details={Name:d.name,Phone:d.phone,Service:C.services.find(s=>s.id===d.service).name,Handover:d.handover==='pickup'?'Pick-up':'Drop-off'};if(d.handover==='pickup')Object.assign(details,{Date:d.date,Time:d.time,Area:d.area,Address:d.address,Landmark:d.landmark});sessionStorage.setItem('bookingConfirmation',JSON.stringify({reference:r.reference,details}));location.href='/book/thanks'}catch{status.innerHTML='<p class="error">We couldn’t confirm delivery of your request. Please contact us on WhatsApp with your details.</p><button type="button" class="btn wa" id="fallbackWa">Send details on WhatsApp</button>';document.getElementById('fallbackWa').onclick=()=>openWA('Laundry booking request\n'+Object.entries(d).filter(([k])=>!['consent','website'].includes(k)).map(([k,v])=>k+': '+v).join('\n'));btn.disabled=false;btn.textContent='Try again'}finally{clearTimeout(slowTimer);f.dataset.sending='false';btn.removeAttribute('aria-busy')}}}
let verificationScript;
let challengeState=null;
function loadVerification(){
 if(window.turnstile)return Promise.resolve();
 if(verificationScript)return verificationScript;
 verificationScript=new Promise((resolve,reject)=>{
  let script=document.createElement('script');
  script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';
  script.async=true;
  let timeout=setTimeout(()=>{verificationScript=null;script.remove();reject(Error('Verification timed out'))},20000);
  script.onload=()=>{clearTimeout(timeout);resolve()};
  script.onerror=()=>{clearTimeout(timeout);verificationScript=null;script.remove();reject(Error('Verification unavailable'))};
  document.head.appendChild(script);
 });
 return verificationScript;
}
function discardChallenge(state){
 if(state.widget!==undefined&&window.turnstile)turnstile.remove(state.widget);
 state.element?.remove();
 if(challengeState===state)challengeState=null;
}
async function getChallenge(){
 if(challengeState&&Date.now()-challengeState.created<240000)return challengeState.promise;
 if(challengeState)discardChallenge(challengeState);
 const state={created:Date.now()};challengeState=state;
 state.promise=(async()=>{
  await loadVerification();
  return new Promise((resolve,reject)=>{
   state.element=document.createElement('div');document.body.appendChild(state.element);
   const timeout=setTimeout(()=>{discardChallenge(state);reject(Error('Verification timed out'))},25000);
   state.widget=turnstile.render(state.element,{sitekey:C.turnstileSiteKey,
    callback:token=>{clearTimeout(timeout);resolve(token)},
    'error-callback':()=>{clearTimeout(timeout);discardChallenge(state);reject(Error('Verification failed'))},
    'expired-callback':()=>{clearTimeout(timeout);discardChallenge(state)}
   });
  });
 })().catch(error=>{discardChallenge(state);throw error});
 return state.promise;
}
render();
